package net.civeira.phylax.feature.identity.tenantloginprovider.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.tenantloginprovider.domain.TenantLoginProvider;
import net.civeira.phylax.feature.identity.tenantloginprovider.domain.valueobject.OidcScopesVO;

class OidcScopesValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of oidc scopes of tenant login provider")
  void test_oidc_scopes_value_holder_assign_plain_value() {
    Object holder = new Object();
    OidcScopesValueHolder<Object> value = new OidcScopesValueHolder<>(holder);
    Assertions.assertSame(holder, value.oidcScopes("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getOidcScopesValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getOidcScopes().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.oidcScopesNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getOidcScopesValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getOidcScopes().isPresent(), "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of oidc scopes of tenant login provider")
  void test_oidc_scopes_value_holder_assign_value_object() {
    Object holder = new Object();
    OidcScopesValueHolder<Object> value = new OidcScopesValueHolder<>(holder);
    OidcScopesVO vo = OidcScopesVO.from("one");
    Assertions.assertFalse(value.getOidcScopesValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.oidcScopes(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getOidcScopesValue().orElseThrow());
    Assertions.assertSame(holder, value.oidcScopes(Optional.empty()));
    Assertions.assertFalse(value.getOidcScopesValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.oidcScopes(Optional.of(vo)));
    Assertions.assertSame(vo, value.getOidcScopesValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of oidc scopes of tenant login provider against the original")
  void test_oidc_scopes_value_holder_read() {
    Object holder = new Object();
    OidcScopesValueHolder<Object> value = new OidcScopesValueHolder<>(holder);
    OidcScopesVO vo = OidcScopesVO.from("one");
    OidcScopesVO other = OidcScopesVO.from("one");
    TenantLoginProvider original = Mockito.mock(TenantLoginProvider.class);
    Mockito.when(original.getOidcScopesValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readOidcScopes(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readOidcScopes(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.oidcScopes(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readOidcScopes(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readOidcScopes(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of oidc scopes of tenant login provider")
  void test_oidc_scopes_value_holder_unset() {
    Object holder = new Object();
    OidcScopesValueHolder<Object> value = new OidcScopesValueHolder<>(holder);
    OidcScopesVO vo = OidcScopesVO.from("one");
    value.oidcScopes(vo);
    Assertions.assertSame(holder, value.unsetOidcScopesIfMatches("oidcScopes_other"));
    Assertions.assertTrue(value.getOidcScopesValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetOidcScopesIfMatches("oidcScopes"));
    Assertions.assertFalse(value.getOidcScopesValue().isPresent(),
        "The field name must clear the value");
    value.oidcScopes(vo);
    Assertions.assertSame(holder, value.unsetOidcScopes());
    Assertions.assertFalse(value.getOidcScopesValue().isPresent(), "Unset must clear the value");
  }
}
